import json
import logging
from typing import List, Tuple, Optional

from langchain_core.documents import Document
from dataiku.core import dkujson

logger = logging.getLogger(__name__)


def enforce_size_limit(docs: List[Document], scores: Optional[List[float]], max_result_size_mb: int) -> Tuple[List[Document], Optional[List[float]]]:
    """
    Enforces a size limit on a list of documents.
    Size is estimated using character count len() on the content and metadata strings.
    
    :param docs: List of documents
    :param scores: Optional list of scores corresponding to the documents
    :param max_result_size_mb: The size limit in MB
    :return: A tuple containing the truncated list of documents and scores (or None if scores was None)
    """
    if max_result_size_mb <= 0:
        return docs, scores

    current_size = 0
    limit_bytes = max_result_size_mb * 1024 * 1024
    
    keep_count = 0
    for doc in docs:
        # We estimate size based on content and metadata
        doc_size = len(doc.page_content.encode('utf-8'))
        if doc.metadata:
            doc_size += len(dkujson.dumps(doc.metadata))
        
        if current_size + doc_size > limit_bytes:
            logger.warning(f"Result size limit of {max_result_size_mb}MB reached. Truncating results from {len(docs)} to {keep_count} documents.")
            break
        
        current_size += doc_size
        keep_count += 1
            
    filtered_docs = docs[:keep_count]
    filtered_scores = scores[:keep_count] if scores is not None else None
    
    return filtered_docs, filtered_scores
